const riyadhDateKey=(offset=0)=>{const value=new Date(Date.now()+offset*86400000),parts=new Intl.DateTimeFormat("en",{timeZone:"Asia/Riyadh",year:"numeric",month:"2-digit",day:"2-digit"}).formatToParts(value),part=(type:string)=>parts.find(item=>item.type===type)?.value||"";return `${part("year")}-${part("month")}-${part("day")}`};
const formatMatchDate=(value:string)=>new Intl.DateTimeFormat("ar-SA",{timeZone:"Asia/Riyadh",weekday:"long",day:"numeric",month:"long"}).format(new Date(`${value}T12:00:00+03:00`));
