  const createSyncId=()=>{const value=Array.from(crypto.getRandomValues(new Uint8Array(24)),byte=>byte.toString(16).padStart(2,"0")).join("");setSyncId(value);localStorage.setItem("navixa-sync-id",value);setSyncStatus("تم إنشاء رمز خاص — احتفظ به لاستعادة بياناتك على جهاز آخر");return value};
  const bytesToBase64=(bytes:Uint8Array)=>{let binary="";for(let i=0;i<bytes.length;i+=0x8000)binary+=String.fromCharCode(...bytes.subarray(i,i+0x8000));return btoa(binary)};
  const base64ToBytes=(value:string)=>Uint8Array.from(atob(value),char=>char.charCodeAt(0));
