  const encryptSyncPayload=async(value:string,passphrase:string)=>{const salt=crypto.getRandomValues(new Uint8Array(16)),iv=crypto.getRandomValues(new Uint8Array(12)),key=await deriveSyncKey(passphrase,salt),cipher=await crypto.subtle.encrypt({name:"AES-GCM",iv},key,new TextEncoder().encode(value));return JSON.stringify({v:1,alg:"AES-GCM",salt:bytesToBase64(salt),iv:bytesToBase64(iv),cipher:bytesToBase64(new Uint8Array(cipher))})};
  const decryptSyncPayload=async(envelope:string,passphrase:string)=>{const box=JSON.parse(envelope);if(box?.alg!=="AES-GCM")throw new Error("invalid");const key=await deriveSyncKey(passphrase,base64ToBytes(box.salt)),plain=await crypto.subtle.decrypt({name:"AES-GCM",iv:base64ToBytes(box.iv)},key,base64ToBytes(box.cipher));return new TextDecoder().decode(plain)};
  const syncUpload=async()=>{if(!betaUsageRemaining("cloudSync")){setSyncStatus("اكتمل حد المزامنة التجريبي لليوم. تظل بياناتك على جهازك ويمكنك التصدير في أي وقت.");return}const id=syncId.trim()||createSyncId();if(syncPassphrase.length<8){setSyncStatus("استخدم كلمة مرور مزامنة من 8 أحرف على الأقل");return}const plain=JSON.stringify({format:"NAVIXA_LOCAL_BACKUP",version:1,data:Object.fromEntries(backupKeys().map(key=>[key,localStorage.getItem(key)]))});setSyncStatus("جارٍ تشفير ورفع بياناتك...");try{const payload=await encryptSyncPayload(plain,syncPassphrase),response=await fetch("/api/sync",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({syncId:id,payload})});if(!response.ok)throw new Error("sync");const usage=consumeBetaUsage("cloudSync");setSyncStatus(`تمت المزامنة المشفرة — متبقي ${usage.remaining} من ${usage.limit} اليوم`) }catch{setSyncStatus("تعذر رفع النسخة المشفرة")}};
